    "text": "‏ أَنَا فَرَطُكُمْ عَلَى الْحَوْضِ، لَيُرْفَعَنَّ إِلَىَّ رِجَالٌ مِنْكُمْ حَتَّى إِذَا أَهْوَيْتُ لأُنَاوِلَهُمُ اخْتُلِجُوا دُونِي فَأَقُولُ أَىْ رَبِّ أَصْحَابِي‏.‏ يَقُولُ لاَ تَدْرِي مَا أَحْدَثُوا بَعْدَكَ ‏.",
