    "text": "انْظُرُوا مَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ مِنْ إِيمَانٍ فَأَخْرِجُوهُ ‏.‏ فَيُخْرَجُونَ مِنْهَا حُمَمًا قَدِ امْتَحَشُوا ‏.‏ فَيُلْقَوْنَ فِي نَهْرِ الْحَيَاةِ أَوِ الْحَيَا فَيَنْبُتُونَ فِي.",
